//! The determinism study (#14): its published table matches the code, two runs and a replay
//! agree at every checkpoint, and any change to the seed or an input shows in the hashes.

use mjk_dynamics::mass::MassProperties;
use mjk_dynamics::{InputLog, RateError, RecordError};
use mjk_math::{Mat3, StateHasher, Vec3};
use mjk_sim::validation::determinism::{
    MASTER_SEED, PilotCommand, Run, STREAMS, ScenarioError, TICKS, determinism_study, markdown,
    record, replay,
};

/// The table the book includes, generated by `mjk validate determinism`.
const PUBLISHED: &str = include_str!("../../../docs/src/validation/determinism.md");

/// The recorded inputs with the thrust of the command at `tick` raised by one part in 10⁹.
fn altered(inputs: &InputLog<PilotCommand>, tick: u64) -> Option<InputLog<PilotCommand>> {
    let mut log = InputLog::with_capacity(inputs.events().len());
    for event in inputs.events() {
        let mut command = event.input;
        if event.tick == tick {
            command.thrust_n *= 1.0 + 1e-9;
        }
        log.record(event.tick, command).ok()?;
    }
    Some(log)
}

fn hashes(run: &Run) -> Vec<u64> {
    run.checkpoints.iter().map(|c| c.hash).collect()
}

#[test]
fn the_published_table_matches_the_code() {
    let (recorded, replayed) = determinism_study().expect("the scenario runs");
    assert_eq!(
        markdown(&recorded, &replayed),
        PUBLISHED,
        "regenerate with: cargo run -p mjk-cli -- validate determinism > docs/src/validation/determinism.md"
    );
}

#[test]
fn two_runs_agree_at_every_checkpoint() {
    let (first, first_inputs) = record(MASTER_SEED).expect("the scenario runs");
    let (second, second_inputs) = record(MASTER_SEED).expect("the scenario runs");
    let ticks: Vec<u64> = first.checkpoints.iter().map(|c| c.tick).collect();
    let expected: Vec<u64> = (0..=10).map(|s| s * 1000).collect();
    assert_eq!(ticks, expected);
    assert_eq!(first, second);
    assert_eq!(first_inputs, second_inputs);
    assert_eq!(first_inputs.events().len(), 20);
}

#[test]
fn replaying_the_inputs_reproduces_the_final_hash() {
    let (recorded, inputs) = record(MASTER_SEED).expect("the scenario runs");
    let replayed = replay(MASTER_SEED, &inputs).expect("the scenario runs");
    assert_eq!(replayed, recorded);
    assert_eq!(
        recorded.checkpoints.last().map(|c| (c.tick, c.hash)),
        Some((TICKS, recorded.final_hash))
    );
    // Every checkpoint fingerprints a different state.
    let mut distinct = hashes(&recorded);
    distinct.sort_unstable();
    distinct.dedup();
    assert_eq!(distinct.len(), 11);
}

#[test]
fn an_altered_input_changes_every_hash_from_its_tick_on() {
    let (recorded, inputs) = record(MASTER_SEED).expect("the scenario runs");
    let replayed =
        replay(MASTER_SEED, &altered(&inputs, 5000).expect("room")).expect("the scenario runs");
    assert_ne!(replayed.final_hash, recorded.final_hash);
    for (a, b) in replayed.checkpoints.iter().zip(&recorded.checkpoints) {
        assert_eq!(a.hash == b.hash, a.tick < 5000, "tick {}", a.tick);
    }
}

#[test]
fn another_seed_changes_every_hash() {
    let (recorded, _) = record(MASTER_SEED).expect("the scenario runs");
    let (other, _) = record(MASTER_SEED + 1).expect("the scenario runs");
    for (a, b) in hashes(&recorded).iter().zip(&hashes(&other)) {
        assert_ne!(a, b);
    }
}

#[test]
fn the_vehicle_tracks_its_commands_and_stays_physical() {
    let (recorded, _) = record(MASTER_SEED).expect("the scenario runs");
    let state = recorded.final_state;
    // The last command has been held for half a second: 4 rate-loop time constants.
    let error = state.angular_velocity - recorded.final_command.rate_rad_s;
    assert!(error.norm() < 0.1, "{error:?}");
    assert!((state.attitude.norm() - 1.0).abs() < 1e-12);
    assert!(state.position.norm().is_finite() && state.velocity.norm() < 100.0);
}

#[test]
fn every_stream_name_hashes_differently() {
    let mut hashes: Vec<u64> = STREAMS
        .iter()
        .map(|name| {
            let mut hasher = StateHasher::new();
            hasher.write_bytes(name.as_bytes());
            hasher.finish()
        })
        .collect();
    hashes.sort_unstable();
    hashes.dedup();
    assert_eq!(hashes.len(), STREAMS.len());
}

#[test]
fn scenario_errors_explain_themselves() {
    let mass =
        MassProperties::new(-1.0, Vec3::zero(), Mat3::identity()).expect_err("negative mass");
    let errors = [
        (
            ScenarioError::from(mass),
            format!("the reference vehicle is not physical: {mass}"),
        ),
        (
            ScenarioError::from(RateError::Zero),
            "a scenario rate is not usable: a rate must be at least 1 Hz".to_owned(),
        ),
        (
            ScenarioError::from(RecordError::Full { capacity: 2 }),
            "a scenario record is too small: the record is full at 2 entries; size it for the \
             whole run"
                .to_owned(),
        ),
    ];
    for (error, message) in errors {
        assert_eq!(error.to_string(), message);
    }
}
